import{_ as p,a0 as l,w as r,s as o,ao as d,I as i,x as s,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"分步指南：安裝和訪問 Kubernetes 儀表板 | LCTT x X-CMD","titleTemplate":false,"description":"分步指南：安裝和訪問 Kubernetes 儀表板 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"分步指南：安裝和訪問 Kubernetes 儀表板 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"分步指南：安裝和訪問 Kubernetes 儀表板 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230717.3 ⭐️⭐️ How to Install and Access Kubernetes Dashboard Step-by-Step","title":"分步指南：安裝和訪問 Kubernetes 儀表板","tag":"202308","desc":""},"relativePath":"202308/20230717.3 ⭐️⭐️ How to Install and Access Kubernetes Dashboard Step-by-Step.md","filePath":"[post].md"}'),h={name:"202308/20230717.3 ⭐️⭐️ How to Install and Access Kubernetes Dashboard Step-by-Step.md"};function b(u,e,c,g,k,m){const a=l("Link");return r(),o("div",null,[e[15]||(e[15]=d(`<h1 id="分步指南-安裝和訪問-kubernetes-儀表板" tabindex="-1">分步指南：安裝和訪問 Kubernetes 儀表板 <a class="header-anchor" href="#分步指南-安裝和訪問-kubernetes-儀表板" aria-label="Permalink to “分步指南：安裝和訪問 Kubernetes 儀表板”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/05/132420lppzypd5fzvhz1dy.jpg" alt=""></p><p>Kubernetes 是一個開源容器編排平台，已成為大規模管理容器化應用的首選解決方案。雖然 Kubernetes 提供了強大的命令列工具來管理集羣，但有時可視化界面可以使監控和管理部署變得更加容易。Kubernetes 儀表板是一個基於 Web 的用户界面，可讓你可視化 Kubernetes 集羣並與之交互。</p><p>在這篇博文中，我們將逐步引導你完成安裝和訪問 Kubernetes Dashboard 的過程，使你能夠簡化 Kubernetes 管理任務。</p><p>先決條件：</p><p>在安裝 Kubernetes Dashboard 之前，請確保你有一個正在運行的 Kubernetes 集羣並具有必要的管理訪問權限。</p><h3 id="安裝-kubernetes-儀表板" tabindex="-1">安裝 Kubernetes 儀表板 <a class="header-anchor" href="#安裝-kubernetes-儀表板" aria-label="Permalink to “安裝 Kubernetes 儀表板”">​</a></h3><p>為集羣安裝 Kubernetes 儀表板的簡單方法是通過 Helm Chart。Kubernetes 儀表板現在依賴於 cert-manager 和 nginx-ingress-controller。幸運的是，可以使用 Helm Chart 自動安裝這些依賴項。但是，如果你已經安裝了這些組件，則可以在安裝 Chart 時通過設置標誌 <code>–set=nginx.enabled=false</code> 和 <code>–set=cert-manager.enabled=false</code> 來禁用它們的安裝。</p><p>事不宜遲，讓我們進入安裝步驟。</p><h4 id="_1-安裝-helm" tabindex="-1">1）安裝 Helm <a class="header-anchor" href="#_1-安裝-helm" aria-label="Permalink to “1）安裝 Helm”">​</a></h4><p>使用終端或命令提示符訪問集羣的主節點。如果沒有安裝，請安裝 helm。運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL -o get_helm.sh https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3</span></span>
<span class="line"><span>$ chmod 700 get_helm.sh</span></span>
<span class="line"><span>$ ./get_helm.sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Install-Helm-on-K8s-master-node.png" alt=""></p><h4 id="_2-添加-kubernetes-儀表板-helm-倉庫" tabindex="-1">2）添加 Kubernetes 儀表板 Helm 倉庫 <a class="header-anchor" href="#_2-添加-kubernetes-儀表板-helm-倉庫" aria-label="Permalink to “2）添加 Kubernetes 儀表板 Helm 倉庫”">​</a></h4><p>運行以下 <code>helm</code> 命令來添加儀表板倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm repo add kubernetes-dashboard https://kubernetes.github.io/dashboard/</span></span>
<span class="line"><span>$ helm repo list</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Helm-Repo-Kubernetes-Dashboard.png" alt=""></p><h4 id="_3-安裝-kubernetes-儀表板" tabindex="-1">3）安裝 Kubernetes 儀表板 <a class="header-anchor" href="#_3-安裝-kubernetes-儀表板" aria-label="Permalink to “3）安裝 Kubernetes 儀表板”">​</a></h4><p>要使用 <code>helm</code> 安裝 Kubernetes 儀表板，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm upgrade --install kubernetes-dashboard kubernetes-dashboard/kubernetes-dashboard --create-namespace --namespace kubernetes-dashboard</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Installing-Kubernetes-Dashboard-Using-Helm-Command.png" alt=""></p><p>上面的輸出確認儀表板已部署在 <code>Kubernetes-dashboard</code> 命名空間中。因此，要訪問儀表板，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl -n kubernetes-dashboard port-forward svc/kubernetes-dashboard-nginx-controller 8443:443</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Port-Forwarding-Kubernetes-Dashboard-Kubectl-Command.png" alt=""></p><p>現在，打開運行上述命令的系統的 Web 瀏覽器，輸入以下 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://localhost:8443</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Accept-Risk-SSL-Kubernetes-Dashboard.png" alt=""></p><p>點擊“<ruby>接受風險並繼續<rt>Accept the Risk and Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Token-For-Kubernetes-Dashboard-Login.png" alt=""></p><p>正如你在上面看到的，我們需要一個令牌才能登錄。因此，讓我們在下一步中生成所需的令牌。</p><h4 id="_4-為-kubernetes-儀表板生成令牌" tabindex="-1">4）為 Kubernetes 儀表板生成令牌 <a class="header-anchor" href="#_4-為-kubernetes-儀表板生成令牌" aria-label="Permalink to “4）為 Kubernetes 儀表板生成令牌”">​</a></h4><p>再打開一個到主節點的 SSH 會話，創建一個服務帳户並使用以下 yaml 文件分配所需的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi k8s-dashboard-account.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: ServiceAccount</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: admin-user</span></span>
<span class="line"><span>  namespace: kube-system</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: rbac.authorization.k8s.io/v1</span></span>
<span class="line"><span>kind: ClusterRoleBinding</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: admin-user</span></span>
<span class="line"><span>roleRef:</span></span>
<span class="line"><span>  apiGroup: rbac.authorization.k8s.io</span></span>
<span class="line"><span>  kind: ClusterRole</span></span>
<span class="line"><span>  name: cluster-admin</span></span>
<span class="line"><span>subjects:</span></span>
<span class="line"><span>- kind: ServiceAccount</span></span>
<span class="line"><span>  name: admin-user</span></span>
<span class="line"><span>  namespace: kube-system</span></span></code></pre></div><p>保存並退出文件。</p><p>接下來通過運行以下命令創建服務帳户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f k8s-dashboard-account.yaml</span></span>
<span class="line"><span>serviceaccount/admin-user created</span></span>
<span class="line"><span>clusterrolebinding.rbac.authorization.k8s.io/admin-user created</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>現在，為管理員用户生成令牌，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl -n kube-system  create token admin-user</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Generate-Token-K8s-Dashboard-kubectl-Command.png" alt=""></p><p>複製此令牌並返回瀏覽器，將其粘貼到“<ruby>輸入令牌<rt>Enter token</rt></ruby>”字段中，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Click-Signin-After-entering-token-kubernetes-dashboard.png" alt=""></p><p>點擊“<ruby>登錄<rt>Login</rt></ruby>”。</p><h4 id="_5-訪問-kubernetes-儀表板" tabindex="-1">5) 訪問 Kubernetes 儀表板 <a class="header-anchor" href="#_5-訪問-kubernetes-儀表板" aria-label="Permalink to “5) 訪問 Kubernetes 儀表板”">​</a></h4><p>當我們點擊上面的“登錄”時，我們將看到以下儀表板：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Kubernetes-Dashboard-Overview-Ubuntu.png" alt=""></p><p>太好了，你現在已登錄 Kubernetes 儀表板。以下是一些需要探索的關鍵特性和功能：</p><ul><li>集羣概覽：獲取集羣運行狀況、資源利用率和運行 Pod 的概覽。</li><li>工作負載：查看和管理你的部署、副本集、有狀態集和守護程序集。</li><li>服務：監控和管理你的服務，包括負載均衡器和外部端點。</li><li>配置：探索你的配置映射、密鑰和持久卷聲明。</li><li>存儲：管理持久卷和存儲類。</li><li>命名空間：在命名空間之間切換以查看和管理不同項目或團隊的資源。</li></ul><p>這就是這篇文章的全部內容，我希望你發現它有用且內容豐富。請在下面的評論部分發表你的疑問和反饋。</p><p><em>（題圖：MJ/1bd0efb0-d4ee-4c8b-854a-49dbf38c5dd7）</em></p><hr>`,50)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),n(a,{href:"https://www.linuxtechi.com/how-to-install-kubernetes-dashboard/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.linuxtechi.com/how-to-install-kubernetes-dashboard/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：",-1)),n(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...e[2]||(e[2]=[s("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),n(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...e[3]||(e[3]=[s("lkxed",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:t(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const y=p(h,[["render",b]]);export{x as __pageData,y as default};
